<template><section class="background-selector"><label><span>Preview background</span><select :value="preview.backgroundType" @change="patch('backgroundType',$event.target.value)"><option value="transparent">Transparent</option><option value="solid">Solid color</option><option value="reference">Bundled reference</option><option value="custom">Session-only custom image</option></select></label><input v-if="preview.backgroundType==='solid'" type="color" :value="preview.color" aria-label="Background color" @input="patch('color',$event.target.value)"><select v-if="preview.backgroundType==='reference'" :value="preview.referenceAssetId" aria-label="Reference background" @change="patch('referenceAssetId',$event.target.value)"><option value="arena">Arena</option><option value="battle">Battle HUD</option><option value="studio">Creator studio</option></select><label v-if="preview.backgroundType==='custom'" class="upload-reference">Choose reference image<input type="file" accept="image/*" @change="$emit('upload',$event)"></label><small>Editor reference only; never included in Preview Mode or runtime data.</small></section></template>
<script setup>const props=defineProps({preview:{type:Object,required:true}}); const emit=defineEmits(['change','upload']); function patch(key,value){emit('change',{...props.preview,[key]:value})}</script>
